tools.example:
model.func().create("rm1", "Ramp");
model.func("rm1").set("location", "0");
model.func("rm1").set("slope", "1/0.1");
model.func("rm1").set("cutoffactive", true);
model.func("rm1").set("cutoff", "1");
model.func("rm1").set("smooth", true);
// use in a boundary condition: V0 = 10[V]*rm1(t[1/s])

model.func().create("rect1", "Rectangle");
model.func("rect1").set("lower", "1e-3");
model.func("rect1").set("upper", "2e-3");
model.func("rect1").set("smooth", true);
model.func("rect1").set("smoothzone", "1e-4");
// heat source: Q0 = 1e6[W/m^3]*rect1(t[1/s])

model.func().create("gp1", "GaussianPulse");
model.func("gp1").set("location", "0");
model.func("gp1").set("sigma", "0.2[mm]");
model.func("gp1").set("normalization", "peak");
model.func("gp1").set("peakvalue", "1");
// spatial beam profile: Q = P0*gp1(x)*gp1(y)

model.func().create("wv1", "Wave");
model.func("wv1").set("type", "square");
model.func("wv1").set("period", "1e-3");
model.func("wv1").set("amplitude", "1");
model.func("wv1").set("smooth", true);
// coil current: I = 2[A]*wv1(t[1/s])

model.func().create("rn1", "Random");
model.func("rn1").set("type", "normal");
model.func("rn1").set("mean", "0");
model.func("rn1").set("normalsigma", "1e-6");
model.func("rn1").set("nargs", "2");
// rough surface: z = z0 + rn1(x, y)

model.func().create("elev1", "Elevation");
model.func("elev1").set("filename", "C:/data/terrain.dem");
model.func("elev1").importData();
// Geometry > Parametric Surface: z = elev1(x, y)

model.func().create("im1", "Image");
model.func("im1").set("filename", "C:/data/mask.png");
model.func("im1").set("xmin", "0"); model.func("im1").set("xmax", "1[mm]");
model.func("im1").set("ymin", "0"); model.func("im1").set("ymax", "1[mm]");
model.func("im1").importData();
// conductivity: sigma = 1e6*im1(x, y) + 1e-3

model.func().create("extf1", "External");
model.func("extf1").set("path", "C:/lib/mymaterial.dll");
model.func("extf1").set("funcs", new String[][]{{"sigma_ext", "2"}});
// use as sigma_ext(T, p) in a material property

model.func().create("mlf1", "MATLAB");
model.func("mlf1").set("funcs", new String[][]{{"myk", "T"}});
% myk.m on the MATLAB path:
% function k = myk(T), k = 400 - 0.05*(T-293); end
// Material: k = myk(T)

model.func().create("lsq1", "LeastSquares");
model.func("lsq1").set("source", "file");
model.func("lsq1").set("filename", "C:/data/k_vs_T.txt");
model.func("lsq1").set("args", "T");
model.func("lsq1").set("exprs", "a+b*T+c*T^2");
model.func("lsq1").importData();

model.func().create("funcsw1", "FunctionSwitch");
model.func("funcsw1").create("an1", "Analytic");
model.func("funcsw1").func("an1").set("funcname", "load");
model.func("funcsw1").func("an1").set("expr", "sin(2*pi*x)");
model.func("funcsw1").create("an2", "Analytic");
model.func("funcsw1").func("an2").set("funcname", "load");
model.func("funcsw1").func("an2").set("expr", "x^2");
// Study: add Function Sweep and pick funcsw1

model.func().create("gp1", "GaussianProcess");
model.func("gp1").set("source", "table");
model.func("gp1").set("table", new String[][]{{"1","10","0.5"},{"2","12","0.7"}});
model.func("gp1").set("args", new String[]{"L","V"});
model.func("gp1").run();  // train

model.component("comp1").cpl().create("aveop1", "Average", "geom1");
model.component("comp1").cpl("aveop1").selection().geom("geom1", 2);
model.component("comp1").cpl("aveop1").selection().set(new int[]{5});
// variable: T_mean = aveop1(T); use in ht: h*(T - T_mean)

model.component("comp1").cpl().create("maxop1", "Maximum", "geom1");
model.component("comp1").cpl("maxop1").selection().all();
// Results > Global Evaluation: maxop1(solid.mises)
// location of the maximum: maxop1(solid.mises, x), maxop1(solid.mises, y)

model.component("comp1").cpl().create("genproj1", "GeneralProjection", "geom1");
model.component("comp1").cpl("genproj1").selection().all();
model.component("comp1").cpl("genproj1").set("srcmap", new String[]{"x", "y"});
// integrate over y: total = genproj1(c) evaluated along the x axis boundary

model.component("comp1").massProp().create("mass1", "MassProperties");
model.component("comp1").massProp("mass1").selection().all();
model.component("comp1").massProp("mass1").set("densitySource", "fromPhysics");
// Results > Global Evaluation: mass1.mass, mass1.CMz, mass1.Izz

model.component("comp1").geom("geom1").feature("fin").set("action", "assembly");
model.component("comp1").geom("geom1").feature("fin").set("createpairs", true);
model.component("comp1").geom("geom1").run();
// pairs p1, p2 ... appear; then in physics:
model.component("comp1").physics("ht").create("cont1", "Continuity", 2);
model.component("comp1").physics("ht").feature("cont1").set("pairs", "p1");
